//! The "scaffolded, not implemented" error channel for `com-amazonaws-s3-amazons3`.
//!
//! @generated by the emulator core scaffold op-stub generator.
//!
//! Every generated operation stub returns [`Scaffolded::not_implemented`], which the
//! framework renders as a protocol-correct **HTTP 501 `NotImplemented`**. Do not change
//! a stub to return a success value: a client, and any check that only asserts the call
//! succeeded, cannot tell an empty success from a real implementation. Implement the
//! operation, or leave the 501.
//!
//! ## The error type
//!
//! A stub's error type is `Scaffolded<{Op}ErrorModeled>` — the model's own error enum
//! plus the `NotImplemented` variant. Do not try to add `NotImplemented` to the
//! `#[operation_error]` enum directly; it accepts only variants the model declares.
//!
//! ## Implementing an operation
//!
//! Replace the `Err(..)` in the handler body with real behaviour. Each stub emits a
//! CONCRETE `impl From<{Op}ErrorModeled> for {Op}Error` beside its
//! alias, so `?` works through the wrapper and a modeled failure needs no ceremony:
//!
//! ```ignore
//! return Err(GetThingErrorModeled::ResourceNotFound(
//!     ResourceNotFound { message: Some("no such thing".into()) },
//! )
//! .into());
//! ```
//!
//! That impl is emitted per operation, not once for all of them — keep it that way if
//! you edit a stub.
//!
//! ## Once the operation is implemented
//!
//! Keep the `#[operation_error]` enum, the alias and the `From` impl.
//!
//! An implemented operation stops needing the 501, but the wrapper is also the only
//! place it can return an error its own model does not declare — `validation` above,
//! for a service whose model carries no client-input error. Delete the wrapper and the
//! handler has no way to refuse a bad request at all.
//!
//! ## Errors S3 documents but its model omits
//!
//! S3's REST API documents failures its Smithy model declares no error shape for
//! (`BucketNotEmpty` 409, `InvalidArgument` 400, `EntityTooLarge` 400, `BadDigest` 400,
//! `ServiceUnavailable` 503, `InternalError` 500, and the bucket-subresource
//! `NoSuchBucketPolicy`/`NoSuchTagSet`/`MalformedPolicy`). A client branches on the HTTP
//! status and the `<Code>`, so those cannot be answered as `ValidationException`;
//! [`Scaffolded::unmodeled`] carries the documented code and status for exactly that
//! case. Anything the model DOES model goes through the modeled channel — widen an
//! operation that omits a shape the service declares with
//! `#[operation_error(.., extra_errors = [".."])]` instead.
//!
//! ## Every error carries a `<Message>`
//!
//! S3's XML error document always carries a `<Message>` beside its `<Code>` — every SDK
//! error parser reads `Error/Message` (botocore reports `None`, or the literal string
//! `"Unknown"`, when it is absent). The three synthetic channels above each serialize
//! their own message member, but EVERY error shape in this service's Smithy model
//! declares no `message` member at all
//! (`smithy_query(query="shape",shape="NoSuchBucket,BucketAlreadyOwnedByYou,…")`), so a
//! modeled error serialized from its members alone would go out code-only. The
//! [`SerializableStruct`] impl for [`Scaffolded`] therefore writes the error code's
//! documented message from [`DOCUMENTED_ERROR_MESSAGES`] before the shape's own members,
//! for every modeled error of every operation — the one place the rule lives.

use aws_smithy_schema::serde::{SerdeError, SerializableStruct, ShapeSerializer};
use aws_smithy_schema::{Schema, ShapeId, ShapeType};
use smithy_server_runtime::OperationError;

/// The `message` member of the synthetic `NotImplemented` error shape.
///
/// `with_xml_name("Message")` matches the casing the restXml / awsQuery error
/// envelopes use, so the same value renders correctly on the XML protocols and as
/// lowercase `message` on the JSON/CBOR ones.
static NOT_IMPLEMENTED_MESSAGE: Schema = Schema::new_member(
    ShapeId::from_static(
        "smithy.framework#NotImplemented$message",
        "smithy.framework",
        "message",
    ),
    ShapeType::String,
    "message",
    0,
)
.with_xml_name("Message");

/// Schema for the synthetic `NotImplemented` error shape.
///
/// Deliberately in the `smithy.framework` namespace: this shape is NOT in any
/// service's model, so it must not collide with a modeled shape. The wire `__type` /
/// `<Code>` comes from [`OperationError::shape_name`] below, not from this schema.
pub static NOT_IMPLEMENTED_SCHEMA: Schema = Schema::new_struct(
    ShapeId::from_static(
        "smithy.framework#NotImplemented",
        "smithy.framework",
        "NotImplemented",
    ),
    ShapeType::Structure,
    &[&NOT_IMPLEMENTED_MESSAGE],
);

/// The payload of a `NotImplemented` failure: which operation was called, and the
/// fact that it is scaffolded rather than broken.
#[derive(Debug, Clone)]
pub struct NotImplemented {
    pub message: String,
}

impl NotImplemented {
    /// A `NotImplemented` naming `operation`.
    ///
    /// The wording matters: it must read as "not written yet", never as "the emulator
    /// is broken", because that distinction is what a human triaging a failing fixture
    /// needs first.
    pub fn new(operation: &str) -> Self {
        Self {
            message: format!(
                "operation {operation} is scaffolded but not implemented in this emulator"
            ),
        }
    }
}

impl std::fmt::Display for NotImplemented {
    fn fmt(&self, f: &mut std::fmt::Formatter<'_>) -> std::fmt::Result {
        write!(f, "NotImplemented: {}", self.message)
    }
}

impl std::error::Error for NotImplemented {}

impl SerializableStruct for NotImplemented {
    fn serialize_members(&self, s: &mut dyn ShapeSerializer) -> Result<(), SerdeError> {
        s.write_string(&NOT_IMPLEMENTED_MESSAGE, self.message.as_str())?;
        Ok(())
    }
}

/// The `message` member of the synthetic `ValidationException` error shape.
static VALIDATION_EXCEPTION_MESSAGE: Schema = Schema::new_member(
    ShapeId::from_static(
        "smithy.framework#ValidationException$message",
        "smithy.framework",
        "message",
    ),
    ShapeType::String,
    "message",
    0,
)
.with_xml_name("Message");

/// Schema for the synthetic `ValidationException` error shape.
///
/// In the `smithy.framework` namespace for the same reason as `NotImplemented`: the
/// shape is not in any service's model, so it must not collide with a modeled one.
/// If THIS service's model declares its own `ValidationException`, prefer that —
/// see [`Scaffolded::validation`].
pub static VALIDATION_EXCEPTION_SCHEMA: Schema = Schema::new_struct(
    ShapeId::from_static(
        "smithy.framework#ValidationException",
        "smithy.framework",
        "ValidationException",
    ),
    ShapeType::Structure,
    &[&VALIDATION_EXCEPTION_MESSAGE],
);

/// The payload of a `ValidationException`: why the request was refused.
#[derive(Debug, Clone)]
pub struct ValidationException {
    pub message: String,
}

impl ValidationException {
    /// A `ValidationException` carrying `message`.
    ///
    /// Say what was wrong with the request and name the member, the way the
    /// boundary validator does — the caller has to fix the request from this text
    /// alone.
    pub fn new(message: impl Into<String>) -> Self {
        Self {
            message: message.into(),
        }
    }
}

impl std::fmt::Display for ValidationException {
    fn fmt(&self, f: &mut std::fmt::Formatter<'_>) -> std::fmt::Result {
        write!(f, "ValidationException: {}", self.message)
    }
}

impl std::error::Error for ValidationException {}

impl SerializableStruct for ValidationException {
    fn serialize_members(&self, s: &mut dyn ShapeSerializer) -> Result<(), SerdeError> {
        s.write_string(&VALIDATION_EXCEPTION_MESSAGE, self.message.as_str())?;
        Ok(())
    }
}

/// The `message` member of a synthetic error shape whose wire code is chosen at
/// runtime ([`Unmodeled`]).
static UNMODELED_MESSAGE: Schema = Schema::new_member(
    ShapeId::from_static(
        "smithy.framework#UnmodeledError$message",
        "smithy.framework",
        "message",
    ),
    ShapeType::String,
    "message",
    0,
)
.with_xml_name("Message");

/// Schema for a synthetic error shape whose wire code is chosen at runtime.
///
/// In the `smithy.framework` namespace for the same reason as the two above: the shape
/// is not in any service's model, so it must not collide with a modeled one. Only the
/// `message` member is on the wire; the code and the status travel on [`Unmodeled`].
pub static UNMODELED_SCHEMA: Schema = Schema::new_struct(
    ShapeId::from_static(
        "smithy.framework#UnmodeledError",
        "smithy.framework",
        "UnmodeledError",
    ),
    ShapeType::Structure,
    &[&UNMODELED_MESSAGE],
);

/// A rejection whose wire error code this service's model does not declare.
///
/// S3's model omits failures its REST API documents, and they are answered through this
/// one channel so the code and status on the wire are the ones S3 sends. The bucket
/// subresource operations are the case it was added for: `PutBucketPolicy`,
/// `GetBucketPolicy`, `PutBucketTagging` and `GetBucketTagging` declare NO errors in the
/// model, yet S3 answers `NoSuchBucket` (404), `NoSuchBucketPolicy` (404),
/// `NoSuchTagSet` (404) and `MalformedPolicy` (400) on them; the object-storage loop
/// uses it for `BucketNotEmpty` (409), `InvalidArgument` (400), `EntityTooLarge` (400),
/// `BadDigest` (400), `ServiceUnavailable` (503) and `InternalError` (500). A client
/// branches on the code, so the code has to be the one S3 sends.
#[derive(Debug, Clone)]
pub struct Unmodeled {
    /// The wire error code (`<Code>` on restXml).
    pub code: &'static str,
    /// The HTTP status this rejection is rendered with.
    pub status: u16,
    /// Why the request was refused.
    pub message: String,
}

impl std::fmt::Display for Unmodeled {
    fn fmt(&self, f: &mut std::fmt::Formatter<'_>) -> std::fmt::Result {
        write!(f, "{}: {}", self.code, self.message)
    }
}

impl std::error::Error for Unmodeled {}

impl SerializableStruct for Unmodeled {
    fn serialize_members(&self, s: &mut dyn ShapeSerializer) -> Result<(), SerdeError> {
        s.write_string(&UNMODELED_MESSAGE, self.message.as_str())?;
        Ok(())
    }
}

/// The `message` member written for a MODELED error whose own shape declares none.
///
/// Same shape as the three synthetic members above — the member name Smithy uses
/// (`message`) with the `Message` element name S3's XML error document carries — so the
/// one value renders as `<Message>` on this service's restXml wire.
static DOCUMENTED_MESSAGE: Schema = Schema::new_member(
    ShapeId::from_static(
        "smithy.framework#DocumentedErrorMessage$message",
        "smithy.framework",
        "message",
    ),
    ShapeType::String,
    "message",
    0,
)
.with_xml_name("Message");

/// The `<Message>` S3 sends for each error code this service's model declares.
///
/// Every error shape in `com.amazonaws.s3` declares no `message` member, yet S3's error
/// document always carries one, and for these codes the text is a fixed, documented
/// constant rather than anything derived from the request — so it belongs here, once,
/// instead of in each handler.
///
/// Sources, per row:
///
/// * the code's entry in AWS's S3 *Error responses* `ErrorCodeList`
///   (<https://docs.aws.amazon.com/AmazonS3/latest/API/ErrorResponses.html#ErrorCodeList>),
///   which publishes the exact text, for the six rows marked `[ErrorCodeList]`; and
/// * otherwise the error shape's own `@documentation` in this service's Smithy model
///   (`smithy_query(query="shape",shape="<Code>",
///   model_path="services/service-com-amazonaws-s3-amazons3/smithy-model/com-amazonaws-s3-amazons3.json")`),
///   HTML stripped — the sentence the model states for that condition.
///
/// `tests/all/error_message_envelope.rs` re-derives the key set from the model and fails
/// if a row is stale or an error shape the model declares has no row, so a model update
/// that adds an error code cannot silently go out message-less.
pub const DOCUMENTED_ERROR_MESSAGES: &[(&str, &str)] = &[
    // [ErrorCodeList]
    ("AccessDenied", "Access Denied"),
    (
        "AnnotationLimitExceeded",
        "The request would exceed the maximum number of annotations allowed per object.",
    ),
    ("AnnotationNameTooLong", "The annotation name exceeds 512 bytes."),
    // [ErrorCodeList]
    (
        "BucketAlreadyExists",
        "The requested bucket name is not available. The bucket namespace is shared by all \
         users of the system. Please select a different name and try again.",
    ),
    // [ErrorCodeList]
    (
        "BucketAlreadyOwnedByYou",
        "Your previous request to create the named bucket succeeded and you already own it.",
    ),
    (
        "EncryptionTypeMismatch",
        "The existing object was created with a different encryption type. Subsequent write \
         requests must include the appropriate encryption parameters in the request or while \
         creating the session.",
    ),
    (
        "IdempotencyParameterMismatch",
        "Parameters on this idempotent request are inconsistent with parameters used in \
         previous request(s).",
    ),
    ("InvalidAnnotationName", "The annotation name you provided is invalid."),
    (
        "InvalidObjectState",
        "Object is archived and inaccessible until restored.",
    ),
    ("InvalidPrefix", "The annotation prefix you provided is invalid."),
    (
        "InvalidRequest",
        "A parameter or header in your request isn't valid. For details, see the description \
         of this API operation.",
    ),
    (
        "InvalidWriteOffset",
        "The write offset value that you specified does not match the current object size.",
    ),
    (
        "NoSuchAnnotation",
        "The specified annotation does not exist on this object.",
    ),
    // [ErrorCodeList], and the same text the unmodeled channel already sends for these
    // two codes on the subresource operations whose model declares no error shape —
    // reused from `state` so one code cannot answer two different messages.
    (
        crate::state::NO_SUCH_BUCKET_CODE,
        crate::state::NO_SUCH_BUCKET_MESSAGE,
    ),
    // [ErrorCodeList]
    (
        crate::state::NO_SUCH_KEY_CODE,
        crate::state::NO_SUCH_KEY_MESSAGE,
    ),
    // [ErrorCodeList]
    (
        "NoSuchUpload",
        "The specified multipart upload does not exist. The upload ID might be invalid, or \
         the multipart upload might have been aborted or completed.",
    ),
    ("NotFound", "The specified content does not exist."),
    (
        "ObjectAlreadyInActiveTierError",
        "This action is not allowed against this storage tier.",
    ),
    (
        "ObjectNotInActiveTierError",
        "The source object of the COPY action is not in the active tier and is only stored in \
         Amazon S3 Glacier.",
    ),
    (
        "TooManyParts",
        "You have attempted to add more parts than the maximum of 10000 that are allowed for \
         this object. You can use the CopyObject operation to copy this object to another and \
         then add more data to the newly copied object.",
    ),
    (
        "UnsupportedMediaType",
        "The annotation payload is not valid UTF-8 encoded text.",
    ),
];

/// The documented `<Message>` for a wire error code, or `None` for a code
/// [`DOCUMENTED_ERROR_MESSAGES`] does not name.
pub fn documented_error_message(code: &str) -> Option<&'static str> {
    DOCUMENTED_ERROR_MESSAGES
        .iter()
        .find(|(candidate, _)| *candidate == code)
        .map(|(_, message)| *message)
}

/// Whether an error shape declares its OWN message member, in which case the handler's
/// value is what goes on the wire and nothing is written for it here.
///
/// No S3 error shape does today; this is what keeps the documented text from being
/// emitted beside a modeled one if the model ever gains it.
fn models_its_own_message(schema: &Schema) -> bool {
    schema.members().iter().any(|member| {
        member
            .member_name()
            .is_some_and(|name| name.eq_ignore_ascii_case("message"))
    })
}

/// An operation's error channel: either the synthetic scaffold signal, or one of the
/// operation's own modeled errors.
#[derive(Debug)]
pub enum Scaffolded<E> {
    /// The operation is generated but has no implementation. Renders as HTTP 501.
    NotImplemented(NotImplemented),
    /// A modeled error the operation declares. Renders with the model's own status.
    Modeled(E),
    /// The request was refused as invalid. Renders as HTTP 400 with the error code
    /// `ValidationException`.
    ///
    /// On the JSON and CBOR protocols that is the same status and code the boundary
    /// validator answers with. Two differences are worth knowing, and neither is
    /// specific to this variant — every handler-returned error shares them:
    /// the awsJson families omit the `x-amzn-errortype` header that the boundary
    /// path sets, and the query protocols render a boundary refusal as
    /// `MalformedQueryString` rather than `ValidationException`, so a client
    /// matching on the error code there sees two codes for one logical failure.
    ValidationException(ValidationException),
    /// A rejection whose code the model does not declare, rendered with the code and
    /// status S3 actually sends. See [`Unmodeled`].
    Unmodeled(Unmodeled),
}

impl<E> Scaffolded<E> {
    /// The scaffold signal for `operation`.
    pub fn not_implemented(operation: &str) -> Self {
        Self::NotImplemented(NotImplemented::new(operation))
    }

    /// Refuse the request as invalid, with HTTP 400 `ValidationException`.
    ///
    /// Reach for this when the request is wrong in a way the model cannot express,
    /// so the boundary validator passed it: a value outside a rule the service
    /// enforces but does not model, or a combination of members that cannot hold
    /// together. Answer it INSTEAD of `not_implemented` — a 501 says "nobody has
    /// written this yet", which is a different claim and is counted as one.
    ///
    /// If this service's model declares its own `ValidationException` (or another
    /// client-input error) use THAT: the modeled shape may carry members beyond
    /// `message` — a `reason`, a field list — and a real client reads them. When the
    /// operation already lists it, it is a plain variant on the generated error enum;
    /// `#[operation_error]`'s `extra_errors` is only for widening in a shape the
    /// SERVICE models that this OPERATION does not list.
    pub fn validation(message: impl Into<String>) -> Self {
        Self::ValidationException(ValidationException::new(message))
    }

    /// Refuse the request with an error code this operation's model does not declare.
    ///
    /// Only for a code the emulated service demonstrably sends where the model names
    /// none — S3's bucket subresource operations model no errors at all, yet answer
    /// `NoSuchBucket`, `NoSuchBucketPolicy`, `NoSuchTagSet` and `MalformedPolicy`, and
    /// the object-storage loop answers `BucketNotEmpty`, `InvalidArgument`,
    /// `EntityTooLarge`, `BadDigest`, `ServiceUnavailable` and `InternalError` the same
    /// way. Prefer a modeled variant whenever the model has one for the failure.
    pub fn unmodeled(code: &'static str, status: u16, message: impl Into<String>) -> Self {
        Self::Unmodeled(Unmodeled {
            code,
            status,
            message: message.into(),
        })
    }
}

impl<E: std::fmt::Display> std::fmt::Display for Scaffolded<E> {
    fn fmt(&self, f: &mut std::fmt::Formatter<'_>) -> std::fmt::Result {
        match self {
            Self::NotImplemented(e) => write!(f, "{e}"),
            Self::Modeled(e) => write!(f, "{e}"),
            Self::ValidationException(e) => write!(f, "{e}"),
            Self::Unmodeled(e) => write!(f, "{e}"),
        }
    }
}

/// `source()` forwards to the modeled error rather than taking the default `None`, so a
/// modeled error's own `source()` is preserved through the wrapper.
impl<E: std::error::Error + 'static> std::error::Error for Scaffolded<E> {
    fn source(&self) -> Option<&(dyn std::error::Error + 'static)> {
        match self {
            Self::NotImplemented(e) => e.source(),
            Self::Modeled(e) => e.source(),
            Self::ValidationException(e) => e.source(),
            Self::Unmodeled(e) => e.source(),
        }
    }
}

/// Every error this service puts on the wire is serialized through here, which is what
/// makes "an S3 error document always carries a `<Message>`" one rule rather than one per
/// operation.
///
/// The three synthetic channels serialize their own message member unchanged. A MODELED
/// error gets the documented message for its wire code written first — `<Code>` then
/// `<Message>`, the order S3's document uses — followed by whatever members its own shape
/// declares (`InvalidObjectState`'s `StorageClass`, say).
impl<E: OperationError> SerializableStruct for Scaffolded<E> {
    fn serialize_members(&self, s: &mut dyn ShapeSerializer) -> Result<(), SerdeError> {
        match self {
            Self::NotImplemented(e) => e.serialize_members(s),
            Self::ValidationException(e) => e.serialize_members(s),
            Self::Unmodeled(e) => e.serialize_members(s),
            Self::Modeled(e) => {
                if !models_its_own_message(e.variant_schema()) {
                    if let Some(message) = documented_error_message(e.shape_name()) {
                        s.write_string(&DOCUMENTED_MESSAGE, message)?;
                    }
                }
                e.as_serializable().serialize_members(s)
            }
        }
    }
}

/// Every `OperationError` method delegates to the modeled error, so wrapping an
/// implemented operation's error channel changes NOTHING about how that error is
/// rendered. Only the synthetic variant behaves differently — and it is the one that
/// must answer 501.
impl<E: OperationError> OperationError for Scaffolded<E> {
    /// The wrapper ITSELF is the serializable view, so the `<Message>` the impl above
    /// writes reaches the wire for a modeled error too. Each variant's own members are
    /// serialized by that impl, by delegation.
    fn as_serializable(&self) -> &dyn SerializableStruct {
        self
    }

    fn variant_schema(&self) -> &'static Schema {
        match self {
            Self::NotImplemented(_) => &NOT_IMPLEMENTED_SCHEMA,
            Self::Modeled(e) => e.variant_schema(),
            Self::ValidationException(_) => &VALIDATION_EXCEPTION_SCHEMA,
            Self::Unmodeled(_) => &UNMODELED_SCHEMA,
        }
    }

    /// The wire error code (`__type` on JSON/CBOR, `<Code>` on XML).
    ///
    /// Keep the literal as it is: changing it changes the wire error code clients match
    /// on. It is intentionally not tied to the Rust variant name.
    fn shape_name(&self) -> &'static str {
        match self {
            Self::NotImplemented(_) => "NotImplemented",
            Self::Modeled(e) => e.shape_name(),
            Self::ValidationException(_) => "ValidationException",
            // The documented wire code this failure carries, not a Rust variant name.
            Self::Unmodeled(e) => e.code,
        }
    }

    /// 501 for the scaffold signal.
    ///
    /// Keep it 501 and not a 5xx server fault: SDK retry classifiers treat those as
    /// retryable, so a client would retry an operation that can never succeed.
    fn http_status(&self) -> u16 {
        match self {
            Self::NotImplemented(_) => 501,
            Self::Modeled(e) => e.http_status(),
            Self::ValidationException(_) => 400,
            Self::Unmodeled(e) => e.status,
        }
    }

    fn query_error_code(&self) -> Option<&'static str> {
        match self {
            // No awsQuery code: the synthetic shape is not in the model, so there is
            // no `awsQueryError` trait to honour. The 501 + `<Code>NotImplemented`
            // envelope carries the signal on the query protocols too.
            Self::NotImplemented(_) => None,
            Self::Modeled(e) => e.query_error_code(),
            Self::ValidationException(_) => None,
            // Same reason: the synthetic shapes carry no `awsQueryError` trait.
            Self::Unmodeled(_) => None,
        }
    }
}
